      "communicates_with": [
        "Finance and Billing",
        "Project and Time Reporting",
        "Notification and Integration",
        "Security and Access Control"
      ]
    },
    {
      "microservice_name": "Project and Time Reporting",
      "responsibility": "Record internal and external activities by employee, date, client, project and role; classify billable and workday-counting time; maintain objectives and work allocations; enforce evidence policies; and produce consolidated hours reports by user, project and organization. Evidence: RF-25, RF-27, RF-28, RF-30, RF-32, pkg com.autentia.tnt.bean.activity.",
      "communicates_with": [
        "Finance and Billing",
        "Administration and Master Data",
        "Notification and Integration",
        "Security and Access Control"
      ]
    },
    {
      "microservice_name": "Finance and Billing",
      "responsibility": "Maintain accounts, transaction types, groups and recurring financial transactions; record accounts receivable and payable via billing records; detail billing items with taxes and attachments; and automatically calculate totals, withholdings, outstanding balances, due dates, and paid status. Evidence: RF-34, RF-36, RF-37, RF-38, RF-44, RF-45, pkg com.autentia.tnt.manager.billing.",
      "communicates_with": [
        "Commercial CRM and Proposals",
        "Project and Time Reporting",
        "Orders and Commissions",
        "Security and Access Control"
      ]
    },
    {
      "microservice_name": "Document Management",
      "responsibility": "Organize versioned documents by category, associate documents with responsible people and organizational areas, and maintain publications, magazines, tutorials and notice boards as institutional knowledge base and internal communication content. Evidence: RF-49, RF-50, RF-51, RF-54, RF-55.",
      "communicates_with": [
        "Security and Access Control",
        "Notification and Integration"
      ]
    },
    {
      "microservice_name": "Orders and Commissions",
      "responsibility": "Record orders and commissions linked to projects, reviewers, collaborators and payment data; control the order workflow states (created, approved, accepted, confirmed, validated, completed); and preserve a textual history of changes. Evidence: RF-58, RF-59, RF-61, RF-62.",
      "communicates_with": [
        "Finance and Billing",
        "Notification and Integration",
        "Security and Access Control"
      ]
    },
    {
      "microservice_name": "Reporting and Exports",
      "responsibility": "Provide reports by business domain (billing, hours, projects, proposals, interactions, organizations, commissions) and export outputs in multiple formats including CSV, PDF, XLS, RTF, HTML, ODT. Evidence: RF-63, RF-64, RF-65, pkg com.autentia.tnt.bean.reports, pkg com.autentia.tnt.report, ext net.sf.jasperreports.",
      "communicates_with": [
        "Finance and Billing",
        "Project and Time Reporting",
        "Commercial CRM and Proposals",
        "Orders and Commissions"
      ]
    },
    {
      "microservice_name": "Security and Access Control",
      "responsibility": "Control access by user profile with scope-based restrictions (full, own records, by area), apply access control to critical entities, and support local and LDAP authentication. Evidence: RNF-66, RNF-67, RNF-68, RNF-69, pkg com.autentia.tnt.manager.security, ext org.acegisecurity.acls.",
      "communicates_with": [
        "People and HR Management"
      ]
    },
    {
      "microservice_name": "Administration and Master Data",
      "responsibility": "Maintain supporting master data used across areas (departments, contract types, user categories, organization types, tax reasons, billing schemes, frequencies) and maintain projects and employment agreements with their periods and rules. Evidence: RF-01, RF-02, RF-03, pkg com.autentia.tnt.manager.admin.",
      "communicates_with": [
        "People and HR Management"
      ]
    },
    {
      "microservice_name": "Notification and Integration",
      "responsibility": "Send email notifications for business events (vacation requests, contract expiry, password reset, pending evidence, orders) and generate interoperable outputs for external consumption. Evidence: RNF-73, RNF-74, role event=4.",
      "communicates_with": []
    }
  ]
}

